#include <iostream>

void runGameSession(int targetNumber) {
    std::cout << "I have a number between 1 and 1000.\n"
              << "Can you guess my number?\n"
              << "Please type your first guess.\n";

    int guess = 0;
    while (std::cout << "? " && std::cin >> guess) {
        if (guess < targetNumber) {
            std::cout << "Too low. Try again.\n";
        } else if (guess > targetNumber) {
            std::cout << "Too high. Try again.\n";
        } else {
            std::cout << "\nExcellent! You guessed the number!\n";
            break;
        }
    }
}

int main() {
    // Deterministic target values matching the textbook test-drive trace
    const int targetNumber = 808;
    int playAgainOption = 0;

    runGameSession(targetNumber);

    std::cout << "Would you like to play again?\n"
              << "Please type ( 1=yes, 2=no )? ";
    if (std::cin >> playAgainOption) {
        if (playAgainOption == 2) {
            // Terminal exit
            return 0;
        }
    }
    return 0;
}

#include <iostream>
#include <string_view>

enum class LicenseType {
    Proprietary,
    OpenSource
};

struct OperatingSystem {
    std::string_view name;
    LicenseType license;
    std::string_view primaryKernel;
};

void displayOSInfo(const OperatingSystem& os) {
    std::cout << "OS: " << os.name << " | Type: "
              << (os.license == LicenseType::OpenSource ? "Open Source" : "Proprietary")
              << " | Kernel Base: " << os.primaryKernel << "\n";
}

int main() {
    // Representative OS entries discussed in sections 1.11.1 - 1.11.4
    constexpr OperatingSystem systems[] = {
        {"Microsoft Windows", LicenseType::Proprietary, "Windows NT"},
        {"GNU/Linux",         LicenseType::OpenSource,  "Linux Kernel"},
        {"Apple macOS/iOS",   LicenseType::Proprietary, "XNU/NeXTSTEP heritage"},
        {"Google Android",    LicenseType::OpenSource,  "Linux Kernel"}
    };

    for (const auto& os : systems) {
        displayOSInfo(os);
    }

    return 0;
}
